python3 - <<'PY'
import subprocess,json,sys
def run(*a):
 return subprocess.run(a,capture_output=True,text=True,timeout=22)
try:
 x=run('docker','inspect','deploy-gaybbs-1')
 if x.returncode:sys.exit(81)
 c=json.loads(x.stdout)[0]
 print('RUNNING='+str(c['State']['Running']).upper())
 print('IMAGE_MATCH='+str(c['Image']==json.loads(run('docker','image','inspect','gace-tgtumbler-gaybbs:local').stdout)[0]['Id']).upper())
 print('RESTART_COUNT='+str(c['RestartCount']))
 p=run('docker','logs','--tail','150','deploy-gaybbs-1')
 lines=(p.stdout+'\n'+p.stderr).splitlines()
 print('BOT_READY='+str(any('GAYBBS_BOT_READY' in l for l in lines)).upper())
 for category,phrase in [('STARTUP_FAIL','GAYBBS_STARTUP_FAILED'),('DATABASE_FAIL','DATABASE_URL_REQUIRED'),('TOKEN_FAIL','BOT_TOKEN'),('MIGRATION_FAIL','migrat'),('RECRUITMENT_FAIL','RECRUITMENT'),('ERROR_LOG','GAYBBS_ERROR')]:
  print(category+'='+str(any(phrase.lower() in l.lower() for l in lines)).upper())
 y=run('docker','inspect','deploy-postgres-1')
 print('DB_RUNNING='+str(json.loads(y.stdout)[0]['State']['Running']).upper() if y.returncode==0 else 'UNKNOWN')
except Exception:sys.exit(89)
PY
